import { AlertDialog, Button, DialogTrigger } from '@strata/react';

export function DeleteCard({ onDelete }: { onDelete: () => Promise<void> }) {
  return (
    <DialogTrigger>
      <Button variant="danger">Delete card</Button>
      <AlertDialog title="Delete this card?" actionLabel="Delete" tone="danger" onAction={onDelete}>
        Scheduled payments on this card will stop. This can’t be undone.
      </AlertDialog>
    </DialogTrigger>
  );
}
